import React, { useEffect, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { Archive, BarChart3, Bell, BookOpen, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, CircleUserRound, Clock3, Cloud, Compass, Dumbbell, Footprints, GripVertical, Heart, Home, Leaf, Lightbulb, ListChecks, LockKeyhole, LogIn, Mail, MessageCircle, MoreHorizontal, NotebookPen, Palette, PanelLeftClose, PanelLeftOpen, Pin, Plus, RefreshCw, Repeat2, Search, Settings, Settings2, Sparkles, Sprout, Timer, Trash2, UserRound, Video, X } from 'lucide-react'
import './styles.css'

const realms=[
  {name:'Fortune',note:'事业与财富',Icon:BriefcaseBusiness,color:'#d8ad60',tint:'#fffdfa',intro:'关于工作、专业能力、收入与长期选择。它不是必须抵达的终点，而是你与现实世界建立关系的方式。',directions:['日常工作','专业成长','财务整理','长期选择']},
  {name:'Beauty',note:'身体与美感',Icon:Heart,color:'#dda2a4',tint:'#fffafb',intro:'照顾身体的感受、能量和外在表达。这里容纳健康、运动、穿搭，以及一切让你更自在的实践。',directions:['身体健康','舒展运动','个人风格','日常护理']},
  {name:'Soul',note:'精神世界',Icon:Leaf,color:'#91b39a',tint:'#fafcfb',intro:'为好奇心、体验与内在感受留下空间。阅读、旅行和创造都可以自然发生，不必证明什么。',directions:['阅读输入','旅行探索','创造表达','独处感受']},
  {name:'Admin',note:'日常运营',Icon:Settings2,color:'#91aace',tint:'#fafbfd',intro:'承接生活里必要但琐碎的部分。日程、家务、资料与关系维护，让生活运行得更轻松。',directions:['日程整理','空间维护','资料归档','关系联络']},
]
const initialTasks=[
  {id:1,title:'整理本周工作材料',tag:'日常工作',time:'今天 15:00',level:'normal'},
  {id:2,title:'预约皮肤科复诊',tag:'日常护理',time:'今天 18:00',level:'late'},
  {id:3,title:'记录三条旅行灵感',tag:'旅行探索',time:'今晚',level:'normal'},
  {id:4,title:'采购游泳用品',tag:'舒展运动',time:'周三之前',level:'normal'},
  {id:5,title:'整理合同资料归档',tag:'资料归档',time:'原定 8月6日',level:'late'},
  {id:6,title:'阅读一篇英语长文',tag:'阅读输入',time:'本周',level:'normal'},
  {id:7,title:'睡眠状态记录',tag:'身体健康',time:'今晚 22:30',level:'normal'},
  {id:8,title:'整理医美功课',tag:'日常护理',time:'原定 8月8日',level:'late'},
]
const directionIcons=[BriefcaseBusiness,BookOpen,Compass,Sparkles],directionNotes=['承接日常里正在发生的具体事情','持续积累相关经验、资料与理解','整理这个方向中的生活内容','为变化和新的可能保留空间'];
const directionStates=['进行中','进行中','未开始','未开始'];
const matters=realms.flatMap(realm=>realm.directions.map((title,index)=>({title,realm:realm.name,state:directionStates[index],note:directionNotes[index],Icon:directionIcons[index],todos:initialTasks.filter(task=>task.tag===title)})))

function Header({title='下午好， May',openModal,navigate}){return <header className="topbar"><div><p className="hello">{title} <span className="wave" aria-hidden="true">🌿</span></p><p className="today">今天是 2026年8月11日，星期二</p></div><div className="head-actions"><button onClick={()=>openModal('search')} aria-label="搜索"><Search/></button><button onClick={()=>openModal('notice')} className="bell" aria-label="通知"><Bell/><i/></button><button className="avatar" onClick={()=>openModal('profilePanel')} aria-label="个人资料">M</button></div></header>}
function Section({title,sub,action,children,className='',id}){const subtitle=sub||(className.includes('full-axis')?'把有明确时间的事情放进一天里':'');return <section id={id} className={`panel ${className}`}><header className="section-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>{children}</section>}
function RealmCard({realm,index,openModal}){const Icon=realm.Icon,show=()=>{window.__boardOpenModal=openModal;openModal(`realmModal-${index}`)};return <article className="realm" onClick={show} style={{'--c':realm.color,'--t':realm.tint}}><div className="realm-top"><span className="realm-icon"><Icon/></span><div><h3>{realm.name}</h3><p>{realm.note}</p></div></div><p className="project-count"><i/> {realm.directions.length} 个生活方向</p><button className="detail" onClick={e=>{e.stopPropagation();show()}}>查看内容 <ChevronRight/></button><span className="watermark"><Icon/></span></article>}
function MatterCard({item,index,openModal,tasks}){const realm=realms.find(r=>r.name===item.realm),Icon=item.Icon,todoCount=tasks.filter(task=>task.tag===item.title&&!task.done).length;return <article className="goal content-card" onClick={()=>openModal(`content-${index}`)} role="button" tabIndex="0" onKeyDown={e=>e.key==='Enter'&&openModal(`content-${index}`)} style={{'--c':realm.color,'--t':realm.tint}}><div className="goal-title"><span><Icon/> {item.title}</span><small>{todoCount} 个待办</small></div><div className="goal-meta"><span>{item.realm} · {item.state}</span></div></article>}
function TodoList({tasks,setTasks,openModal,full=false}){const toggle=id=>setTasks(v=>v.map(t=>t.id===id?{...t,done:!t.done}:t));const remove=id=>setTasks(v=>v.filter(t=>t.id!==id));return <><div className="tasks">{tasks.map(t=><article className={t.done?'done':''} key={t.id}><GripVertical className="drag"/><button className="task-check" onClick={()=>toggle(t.id)} aria-label={`完成${t.title}`}><Check/></button><button className="task-copy" onClick={()=>openModal(`todoEdit-${t.id}`)}><b>{t.title}</b>{t.level==='late'&&<em>已逾期</em>}<small>{t.tag} · {t.time}</small></button><button className="task-remove" onClick={()=>remove(t.id)} aria-label={`删除${t.title}`}><X/></button></article>)}</div><button className="add-todo" onClick={()=>openModal('addTodo')}><Plus/> 添加待办</button>{!full&&<button className="more-page" onClick={()=>openModal('gotoTodo')}>进入待办页面 <ChevronRight/></button>}</>}

function TodayTodoPreview({tasks,navigate}){const active=tasks.filter(t=>!t.done);return <Section title="今日待办" className="today-todo card-list-todo" action={<b className="running">{active.length} 项进行中</b>}><div className="stats"><div><b>{active.length}</b><span>进行中</span></div><div><b>4</b><span>已安排</span></div><div><b>{tasks.filter(t=>t.done).length}</b><span>已完成</span></div></div><div className="todo-sub"><span>正在推进</span><button>按重要排序 <ChevronDown/></button></div><div className="dashboard-task-scroll"><div className="tasks">{active.map(t=><article key={t.id}><GripVertical className="drag"/><button className="task-check" onClick={()=>navigate('todo')} aria-label={`打开${t.title}`}><Check/></button><div><b>{t.title}</b>{t.level==='late'&&<em>已逾期</em>}<small>{t.tag} · {t.time}</small></div><button className="task-remove" onClick={()=>navigate('todo')} aria-label="打开待办"><X/></button></article>)}</div></div></Section>}
function ScheduleTodoPanel({tasks,scheduled,navigate,openModal}){const [sortMode,setSortMode]=useState('manual'),[sortOpen,setSortOpen]=useState(false),sortLabels={manual:'手动排序',time:'按时间',realm:'按板块',status:'按状态'},active=tasks.filter(t=>!t.done),isTimed=t=>scheduled.some(s=>s.taskId===t.id)||/\d{1,2}:\d{2}/.test(t.time),rank=t=>realms.findIndex(r=>r.directions.includes(t.tag)),sortItems=items=>{const list=[...items];if(sortMode==='time')return list.sort((a,b)=>a.time.localeCompare(b.time,'zh-CN'));if(sortMode==='realm')return list.sort((a,b)=>rank(a)-rank(b));if(sortMode==='status')return list.sort((a,b)=>(b.level==='late')-(a.level==='late'));return list},progress=sortItems(active.filter(isTimed)),anytime=sortItems(active.filter(t=>!isTimed(t)));const Cards=({items})=><div className="tasks">{items.map(t=>{const arranged=scheduled.some(s=>s.taskId===t.id);return <article className={arranged?'arranged':''} draggable onDragStart={e=>{e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('text/plain',JSON.stringify(t))}} key={t.id}><GripVertical className="drag"/><button className="task-check" onClick={()=>navigate(`todoEdit-${t.id}`)}><Check/></button><button className="task-copy" onClick={()=>navigate(`todoEdit-${t.id}`)}><b>{t.title}</b>{t.level==='late'&&<em>已逾期</em>}<small>{t.tag} · {arranged?'已放入时间轴':t.time}</small></button><button className="task-remove" onClick={()=>navigate(`todoEdit-${t.id}`)}><X/></button></article>})}</div>;return <Section id="today-todos" title="今日待办" className="today-todo card-list-todo schedule-todos" action={<button className="quick-add-todo" onClick={()=>openModal('addTodo')}><Plus/> 新增待办</button>}><div className="stats"><div><b>{active.length}</b><span>进行中</span></div><div><b>{scheduled.length}</b><span>已安排</span></div><div><b>{tasks.filter(t=>t.done).length}</b><span>已完成</span></div></div><div className="todo-sub"><span>正在推进</span><div className="todo-sort-wrap"><button className="todo-sort-trigger" onClick={()=>setSortOpen(v=>!v)} aria-expanded={sortOpen}><Settings2/><span>{sortLabels[sortMode]}</span><ChevronDown/></button>{sortOpen&&<div className="todo-sort-menu">{Object.entries(sortLabels).map(([value,label])=><button className={sortMode===value?'active':''} onClick={()=>{setSortMode(value);setSortOpen(false)}} key={value}><span>{label}</span>{sortMode===value&&<Check/>}</button>)}</div>}</div></div><div className="dashboard-task-scroll grouped-task-scroll"><Cards items={progress}/><div className="anytime-heading"><span>随时待办</span></div><Cards items={anytime}/></div></Section>}
function PlanningBoard({tasks,navigate,openModal}){const slotHeight=64,hours=Array.from({length:24},(_,i)=>i),scroller=useRef(null),[scheduled,setScheduled]=useState([]),[now,setNow]=useState(()=>new Date()),[selectedDate,setSelectedDate]=useState(()=>new Date());const dateKey=d=>`${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`,todayKey=dateKey(now),selectedKey=dateKey(selectedDate),isToday=selectedKey===todayKey,nowMinutes=now.getHours()*60+now.getMinutes(),nowTop=nowMinutes/60*slotHeight,nowLabel=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,dateLabel=`${selectedDate.getMonth()+1}月${selectedDate.getDate()}日`,axisTitle=isToday?'今日时间轴':`${dateLabel}时间轴`;const focusNow=()=>requestAnimationFrame(()=>{if(scroller.current)scroller.current.scrollTo({top:Math.max(0,nowTop-scroller.current.clientHeight*.42),behavior:'smooth'})});useEffect(()=>{const timer=setInterval(()=>setNow(new Date()),60000);focusNow();return()=>clearInterval(timer)},[]);const changeDate=amount=>setSelectedDate(d=>{const next=new Date(d);next.setDate(next.getDate()+amount);return next}),goToday=()=>{setSelectedDate(new Date());focusNow()};const dayScheduled=scheduled.filter(s=>s.dateKey===selectedKey),drop=(e,hour)=>{e.preventDefault();try{const t=JSON.parse(e.dataTransfer.getData('text/plain'));setScheduled(v=>v.some(s=>s.taskId===t.id&&s.dateKey===selectedKey)?v.map(s=>s.taskId===t.id&&s.dateKey===selectedKey?{...s,start:hour}:s):[...v,{id:Date.now(),taskId:t.id,title:t.title,start:hour,duration:1,dateKey:selectedKey}])}catch{}};const resize=(e,id)=>{e.preventDefault();e.stopPropagation();const startY=e.clientY,current=scheduled.find(s=>s.id===id);const move=ev=>{const change=Math.round((ev.clientY-startY)/(slotHeight/2))/2;setScheduled(v=>v.map(s=>s.id===id?{...s,duration:Math.max(.5,Math.min(24-s.start,current.duration+change))}:s))};const up=()=>{document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up)};document.addEventListener('mousemove',move);document.addEventListener('mouseup',up)};const toneFor=s=>{const task=tasks.find(t=>t.id===s.taskId),realm=realms.find(r=>r.directions.includes(task?.tag));return realm||realms[3]};const dateControls=<div className="axis-date-controls"><button onClick={()=>changeDate(-1)} aria-label="前一天"><ChevronLeft/></button><span><CalendarDays/>{dateLabel}</span><button onClick={()=>changeDate(1)} aria-label="后一天"><ChevronRight/></button><button className="today-shortcut" onClick={goToday} disabled={isToday}>今天</button></div>;return <div className="bottom planning-board"><Section title={axisTitle} className="timeline-panel full-axis" action={dateControls}><div className="axis-scroll" ref={scroller}><div className="axis-grid">{hours.map(h=><div className="hour-row" onDragOver={e=>e.preventDefault()} onDrop={e=>drop(e,h)} key={h}><time>{String(h).padStart(2,'0')}:00</time><i/></div>)}{isToday&&<div className="current-time-line" style={{top:nowTop}} aria-label={`当前时间 ${nowLabel}`}><time>{nowLabel}</time><span/><i/></div>}{dayScheduled.map(s=>{const tone=toneFor(s);return <article className="scheduled-block" style={{top:s.start*slotHeight+2,height:s.duration*slotHeight-4,'--schedule-color':tone.color,'--schedule-tint':tone.tint}} key={s.id}><b>{s.title}</b><small>{String(s.start).padStart(2,'0')}:00 · {s.duration}小时</small><button className="resize-handle" onMouseDown={e=>resize(e,s.id)} aria-label="调整时长"/></article>})}</div></div></Section><ScheduleTodoPanel tasks={tasks} scheduled={dayScheduled} navigate={navigate} openModal={openModal}/></div>}
function MobileOverview({tasks,openModal}){const active=tasks.filter(t=>!t.done),done=tasks.filter(t=>t.done),scheduled=active.filter(t=>/\d{1,2}:\d{2}/.test(`${t.meta||''} ${t.time||''}`));return <section className="mobile-overview" aria-label="今日概览"><header><div><small>2026年8月11日 · 星期二</small><h2>今天，慢慢来就好</h2></div></header><div className="mobile-overview-stats"><article><b>{active.length}</b><span>正在推进</span></article><article><b>{scheduled.length}</b><span>已有安排</span></article><article><b>{done.length}</b><span>今日完成</span></article></div><div className="mobile-overview-actions"><button className="primary" onClick={()=>openModal('addTodo')}><Plus/>记一件待办</button><button onClick={()=>document.getElementById('today-plan')?.scrollIntoView({behavior:'smooth'})}><Clock3/>看看今天</button></div></section>}

function Dashboard({navigate,openModal,tasks,setTasks}){return <><div id="dashboard-top"><Header openModal={openModal} navigate={navigate}/></div><MobileOverview tasks={tasks} openModal={openModal}/><Section id="life-map" title="人生版图" sub="四个生活板块，以及它们正在容纳的方向" action={<button className="outline" onClick={()=>openModal('addDirection')}><Plus/> 新建方向</button>}><div className="realms">{realms.map((r,i)=><RealmCard realm={r} index={i} openModal={openModal} key={r.name}/>)}</div></Section><Section id="life-content" title="生活内容" sub="每个方向承接一类生活内容，再自然拆成每天可做的小事" action={<button className="outline matter-add" onClick={()=>openModal('addDirection')}><Plus/> 新建事项</button>}><LinkedMatters openModal={openModal} tasks={tasks}/></Section><div id="today-plan"><PlanningBoard tasks={tasks} navigate={navigate} openModal={openModal}/></div><LifeReview tasks={tasks} navigate={navigate}/></>}

function MapPage({navigate,openModal}){return <><Header title="人生版图" openModal={openModal} navigate={navigate}/><div className="page-intro"><span>生活方向</span><h1>这里不是目标清单，<br/>只是生活展开的几种方式。</h1><p>板块帮助你理解自己正在关心什么。方向可以出现、变化或暂时沉睡，不需要被完成。</p></div><div className="map-page-grid">{realms.map((r,i)=>{const Icon=r.Icon;return <article style={{'--c':r.color,'--t':r.tint}} key={r.name}><header><span><Icon/></span><div><h2>{r.name}</h2><p>{r.note}</p></div><button onClick={()=>navigate(`realm-${i}`)}><ChevronRight/></button></header><p className="realm-intro">{r.intro}</p><div className="direction-list">{r.directions.map(d=><button key={d} onClick={()=>navigate('matters')}><i/>{d}<ChevronRight/></button>)}</div></article>})}</div></>}
function RealmPage({realm,navigate,openModal}){const Icon=realm.Icon;return <><Header title={realm.name} openModal={openModal} navigate={navigate}/><button className="back" onClick={()=>navigate('map')}><ChevronLeft/> 返回版图</button><section className="realm-hero" style={{'--c':realm.color,'--t':realm.tint}}><span><Icon/></span><p>{realm.note}</p><h1>{realm.intro}</h1></section><Section title="这个板块包含的方向" sub="它们是内容的索引，不是必须完成的目标"><div className="direction-detail">{realm.directions.map((d,i)=><article key={d}><span>0{i+1}</span><h3>{d}</h3><p>{['最近的想法、相关资料与正在发生的事情，都可以放在这里。','保留过程和感受，允许它根据生活状态自然变化。'][i%2]}</p><button onClick={()=>navigate('matters')}>查看相关事项 <ChevronRight/></button></article>)}</div></Section><Section title="最近留下的内容" sub="关于这个板块的片段与记录"><div className="notes-grid"><button onClick={()=>openModal('note')}><Plus/><b>写一条新记录</b><small>想法、感受或一个小发现</small></button><article><time>8月8日</time><p>最近开始更在意过程是否舒服，而不是有没有明显结果。</p></article><article><time>8月3日</time><p>有些方向暂时不动，也不代表它们被放弃了。</p></article></div></Section></>}
function MattersPage({navigate,openModal}){return <><Header title="事项与日常" openModal={openModal} navigate={navigate}/><div className="page-intro compact life-intro"><span>生活近况</span><h1>整理正在发生的生活。</h1><p>这里不衡量完成，也不催促结果。只是把方向、内容和最近的感受放在容易找到的地方。</p></div><section className="life-overview"><div><b>7</b><span>正在展开的事项</span></div><div><b>4</b><span>生活板块</span></div><div><b>12</b><span>最近留下的内容</span></div><p><Sparkles/> 最近更常回到“身体与美感”，也收集了不少旅行灵感。</p></section><div className="filter-row life-filters"><button className="active">全部</button>{realms.map(r=><button key={r.name}>{r.name}</button>)}<button className="outline push" onClick={()=>openModal('addMatter')}><Plus/> 添加事项</button></div><div className="life-management"><main><div className="content-heading"><div><h2>正在展开</h2><p>按当下状态自然排列</p></div><button><ChevronDown/> 最近关注</button></div><div className="matter-board life-board">{matters.map(m=>{const r=realms.find(x=>x.name===m.realm),Icon=m.Icon;return <article style={{'--c':r.color,'--t':r.tint}} key={m.title} onClick={()=>openModal('matterDetail')}><header><span><Icon/></span><i>{m.realm}</i><button><MoreHorizontal/></button></header><h2>{m.title}</h2><p>{m.note}</p><div className="content-tags"><span>相关记录</span><span>灵感与资料</span></div><footer><span>{m.state}</span><button>查看内容 <ChevronRight/></button></footer></article>})}</div></main><aside className="life-aside"><section><header><h3>日常照顾</h3><button onClick={()=>openModal('addRoutine')}><Plus/></button></header><button className="care-item"><span><Heart/></span><div><b>喝水与舒展</b><small>今天身体感觉如何？</small></div></button><button className="care-item"><span><Clock3/></span><div><b>睡前离开屏幕</b><small>给睡眠一点准备时间</small></div></button><button className="care-item"><span><BookOpen/></span><div><b>记录今天</b><small>一句话也足够</small></div></button></section><section><header><h3>最近留下</h3><button onClick={()=>openModal('note')}><Plus/></button></header><article className="life-note"><time>8月8日</time><p>有些事情没有明显进展，但我和它的关系正在慢慢改变。</p></article><article className="life-note"><time>8月5日</time><p>最近想把游泳重新放回生活里。</p></article></section></aside></div></>}
function TodoPage({navigate,openModal,tasks,setTasks}){return <><Header title="待办事项" openModal={openModal} navigate={navigate}/><div className="todo-page-head"><div><span>今天</span><h1>待办事项</h1><p>只放需要被提醒的具体事情，其余生活不必都变成任务。</p></div><button onClick={()=>openModal('addTodo')}><Plus/> 新建待办</button></div><div className="todo-layout"><aside><button className="active">今天 <b>{tasks.length}</b></button><button>即将到来 <b>3</b></button><button>收集箱 <b>2</b></button><hr/><h3>按领域</h3>{realms.map(r=><button key={r.name}><i style={{background:r.color}}/>{r.name}</button>)}</aside><Section title="今天" sub="2026年8月10日" action={<button className="sort">按时间排序 <ChevronDown/></button>}><div className="stats"><div><b>{tasks.filter(t=>!t.done).length}</b><span>未完成</span></div><div><b>{tasks.filter(t=>t.level==='late').length}</b><span>已逾期</span></div><div><b>{tasks.filter(t=>t.done).length}</b><span>已完成</span></div></div><TodoList tasks={tasks} setTasks={setTasks} openModal={openModal} full/></Section></div></>}
function ProfilePage({navigate,openModal}){const rows=[{title:'生活记录',desc:'回看内容与生活片段',icon:CheckCircle2,action:()=>navigate('matters'),tone:'green'},{title:'账户与同步',desc:'管理账号信息与多端同步',icon:RefreshCw,action:()=>openModal('sync'),tone:'blue'},{title:'归档内容',desc:'查看暂时收起的方向与内容',icon:Archive,action:()=>openModal('archive'),tone:'amber'}],settings=[{title:'外观与偏好',desc:'调整主题、颜色与显示方式',icon:Palette,action:()=>openModal('settings'),tone:'violet'},{title:'通知设置',desc:'选择希望收到的生活提醒',icon:Bell,action:()=>openModal('notice'),tone:'rose'},{title:'帮助与反馈',desc:'使用帮助、常见问题与建议',icon:CircleHelp,action:()=>openModal('help'),tone:'blue'}];const List=({items})=><div className="profile-list">{items.map(({title,desc,icon:Icon,action,tone})=><button key={title} onClick={action}><span className={tone}><Icon/></span><div><b>{title}</b><small>{desc}</small></div><ChevronRight/></button>)}</div>;return <><Header title="我的空间" openModal={openModal} navigate={navigate}/><div className="profile-wrap"><button className="back profile-back" onClick={()=>navigate('today')}><ChevronLeft/> 返回今日</button><header className="profile-heading"><div><h1>我的</h1><p>管理你的个人空间与应用设置</p></div></header><section className="profile-card"><span className="profile-avatar">M</span><div><h2>May</h2><p>登录后同步多端数据</p></div><button onClick={()=>openModal('profile')}>编辑资料</button></section><section className="profile-group"><h3>个人空间</h3><List items={rows}/></section><section className="profile-group"><h3>应用设置</h3><List items={settings}/></section><aside className="profile-quote"><Leaf/><div><b>把生活整理成自己喜欢的样子。</b><p>保持好奇，也允许每一种节奏自然发生。</p></div><i/><i/></aside></div></>}
function ProfilePanel({close,openModal}){const groups=[{title:'个人空间',items:[['生活记录','回看最近留下的生活片段',CheckCircle2,'green','archive'],['账户与同步','登录后同步多端生活数据',Cloud,'blue','login'],['归档内容','查看暂时收起的内容',Archive,'amber','archive']]},{title:'应用设置',items:[['外观与偏好','调整颜色与显示方式',Palette,'violet','settings'],['通知设置','选择希望收到的提醒',Bell,'rose','notice'],['帮助与反馈','查看帮助或留下建议',CircleHelp,'blue','help']]}];return <div className="notice-backdrop" onClick={close}><aside className="notification-panel profile-panel" onClick={e=>e.stopPropagation()}><header><div><h2>我的空间</h2></div><button onClick={close}><X/></button></header><div className="profile-panel-scroll"><section className="profile-panel-card"><span>M</span><div><b>May</b><small>登录后可在不同设备同步生活数据</small></div><button className="profile-login-button" onClick={()=>openModal('login')}><LogIn/> 登录并同步</button></section>{groups.map(group=><section className="profile-panel-group" key={group.title}><h3>{group.title}</h3><div>{group.items.map(([title,desc,Icon,tone,type])=><button key={title} onClick={()=>openModal(type)}><span className={tone}><Icon/></span><p><b>{title}</b><small>{desc}</small></p><ChevronRight/></button>)}</div></section>)}</div><footer><button><UserRound/> 游客状态</button><button onClick={close}>返回今日 <ChevronRight/></button></footer></aside></div>}

function LoginModal({close}){const [mode,setMode]=useState('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState('');const submit=e=>{e.preventDefault();setMessage('登录界面已就绪，填入 Supabase 项目地址与公开密钥后即可启用真实同步。')};return <div className="modal-backdrop login-backdrop" onClick={close}><section className="login-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close} aria-label="关闭"><X/></button><header><span><Cloud/></span><div><h2>{mode==='login'?'登录小栖':'创建小栖账号'}</h2><p>把生活数据安全地同步到自己的 Supabase 空间</p></div></header><form onSubmit={submit}><label><span>邮箱</span><div><Mail/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com" required/></div></label><label><span>密码</span><div><LockKeyhole/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="至少 6 位" minLength={6} required/></div></label><button className="login-submit" type="submit"><LogIn/>{mode==='login'?'登录并开始同步':'注册并开始同步'}</button></form>{message&&<p className="login-status"><Cloud/>{message}</p>}<div className="login-switch"><span>{mode==='login'?'还没有账号？':'已经有账号？'}</span><button onClick={()=>{setMode(mode==='login'?'signup':'login');setMessage('')}}>{mode==='login'?'创建账号':'返回登录'}</button></div><small className="login-note">当前项目保留了旧版 user_boards 数据结构；正式连接后，每位用户只会读写自己的数据。</small></section></div>}
function RealmModal({realm,close,tasks,setTasks}) {
  const Icon=realm.Icon, icons=[Video,Footprints,BookOpen,Sparkles], statusOptions=['未开始','进行中','已结束'];
  const [directions,setDirections]=useState(realm.directions), [statuses,setStatuses]=useState(()=>realm.directions.map((_,i)=>directionStates[i%4])), [subtitle,setSubtitle]=useState(realm.note?[realm.note,'探索与成长'].filter(Boolean).join(' · '):''), [adding,setAdding]=useState(false), [draft,setDraft]=useState(''), [selectedIndex,setSelectedIndex]=useState(null), [todoDraft,setTodoDraft]=useState(''), [directionNotes,setDirectionNotes]=useState(()=>realm.directions.map((d,i)=>`${d}承接这一方向里持续发生的内容、经验与具体行动。`));
  const add=()=>{if(draft.trim()){setDirections(v=>[...v,draft.trim()]);setStatuses(v=>[...v,'未开始'])}setDraft('');setAdding(false)};
  const saveSubtitle=()=>{realm.note=subtitle.trim()};
  const cycleStatus=i=>setStatuses(v=>v.map((status,n)=>n===i?statusOptions[(statusOptions.indexOf(status)+1)%statusOptions.length]:status));
  const openDirection=i=>setSelectedIndex(current=>current===i?null:i);
  const selectedTitle=selectedIndex===null?'':directions[selectedIndex], linkedTasks=tasks.filter(task=>task.tag===selectedTitle), activeTasks=linkedTasks.filter(task=>!task.done), completedTasks=linkedTasks.filter(task=>task.done);
  const addTodo=()=>{if(!todoDraft.trim()||selectedIndex===null)return;setTasks(v=>[...v,{id:Date.now(),title:todoDraft.trim(),tag:selectedTitle,time:'未设置时间',level:'normal'}]);setTodoDraft('')};
  return <div className="modal-backdrop realm-backdrop" onClick={close}><section className="realm-modal simple-realm-modal refined-realm-modal" style={{'--c':realm.color,'--t':realm.tint}} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><header><span><Icon/></span><div className="realm-head-copy"><h2>{realm.name}</h2><input aria-label="板块副标题" value={subtitle} onChange={e=>setSubtitle(e.target.value)} onBlur={saveSubtitle} onKeyDown={e=>e.key==='Enter'&&e.currentTarget.blur()} placeholder=""/></div><div className="header-summary"><article><b>{statuses.filter(s=>s==='进行中').length}</b><span>进行中</span></article><article><b>{statuses.filter(s=>s==='未开始').length}</b><span>未开始</span></article><article><b>{statuses.filter(s=>s==='已结束').length}</b><span>已结束</span></article></div></header><div className="realm-modal-body"><div className="realm-modal-title"><div><h3>方向一览</h3><p>长期经营、持续探索，也允许它们自然变化</p></div><button onClick={()=>setAdding(true)}><Plus/> 新建方向</button></div>{adding&&<div className="add-direction-form"><input autoFocus value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>e.key==='Enter'&&add()} placeholder="输入方向名称"/><button onClick={add}>添加</button><button onClick={()=>setAdding(false)}>取消</button></div>}<div className="modal-directions direction-profile-grid">{directions.map((d,i)=>{const DIcon=icons[i%icons.length];return <article className={selectedIndex===i?'is-expanded':''} onClick={()=>openDirection(i)} onKeyDown={e=>e.key==='Enter'&&openDirection(i)} role="button" tabIndex="0" key={`${d}-${i}`}><button className={`direction-profile-state status-${statusOptions.indexOf(statuses[i])}`} onClick={e=>{e.stopPropagation();cycleStatus(i)}}><i/>{statuses[i]}</button><div className="direction-profile-icon"><DIcon/></div><h4>{d}</h4><span>{realm.note}</span><footer><small>最近更新 · {['今天','2天前','5天前','1周前'][i%4]}</small></footer></article>})}</div>{selectedIndex!==null&&<section className="direction-inline-manager"><header><div className="manager-title"><span>{React.createElement(icons[selectedIndex%icons.length])}</span><div><small>{realm.name} · 方向内容</small><h3>{selectedTitle}</h3></div></div><div className="manager-counts"><span><b>{activeTasks.length}</b> 正在发生</span><span><b>{completedTasks.length}</b> 最近完成</span></div></header><div className="manager-note"><label>方向说明</label><textarea value={directionNotes[selectedIndex]} onChange={e=>setDirectionNotes(v=>v.map((note,i)=>i===selectedIndex?e.target.value:note))}/></div><div className="manager-columns"><section><div className="manager-heading"><div><h4>具体内容</h4><p>这里的每一项都可以继续落到每日待办</p></div></div><div className="inline-task-list">{activeTasks.map(task=><article key={task.id}><span><ListChecks/></span><div><b>{task.title}</b><small>{task.time}</small></div></article>)}{!activeTasks.length&&<p className="inline-empty">还没有具体内容，可以从一件小事开始。</p>}</div><div className="inline-add"><input value={todoDraft} onChange={e=>setTodoDraft(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addTodo()} placeholder="添加一项具体内容或待办…"/><button onClick={addTodo}><Plus/> 添加</button></div></section><aside><div className="manager-heading"><div><h4>近期完成</h4><p>保留已经发生过的生活痕迹</p></div></div><div className="inline-completed">{completedTasks.slice(0,4).map(task=><article key={task.id}><CheckCircle2/><div><b>{task.title}</b><small>{task.time}</small></div></article>)}{!completedTasks.length&&<p className="inline-empty">完成后的内容会留在这里。</p>}</div></aside></div></section>}</div></section></div>
}

function QuickTodoModal({close,setTasks}){const [title,setTitle]=useState(''),[tag,setTag]=useState('日常工作'),[reminder,setReminder]=useState('随时待办'),[advanced,setAdvanced]=useState(false),[directionOpen,setDirectionOpen]=useState(false),[date,setDate]=useState('2026-08-11'),[time,setTime]=useState(''),[duration,setDuration]=useState('1小时'),[note,setNote]=useState('');const realm=realms.find(r=>r.directions.includes(tag))||realms[0],save=()=>{if(!title.trim())return;const taskTime=advanced?(time?`${date} ${time}`:date):reminder;setTasks(v=>[...v,{id:Date.now(),title:title.trim(),tag:advanced?tag:'收集箱',time:taskTime,level:'normal',duration:advanced?duration:'未设置',note:advanced?note:''}]);close()};return <div className="modal-backdrop quick-todo-backdrop" onClick={close}><section className="quick-todo-modal" style={{'--c':realm.color,'--t':realm.tint}} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close} aria-label="关闭"><X/></button><header><span><ListChecks/></span><div><h2>新建待办</h2><p>先记下来，之后再决定如何安排</p></div></header><label className="quick-title"><span>准备做什么？</span><input autoFocus value={title} onChange={e=>setTitle(e.target.value)} onKeyDown={e=>e.key==='Enter'&&!advanced&&save()} placeholder="输入一件具体的事情…"/></label><div className="quick-reminders">{['随时待办','今天','明天'].map((item,i)=>{const RIcon=[ListChecks,CalendarDays,Clock3][i];return <button className={reminder===item?'active':''} onClick={()=>setReminder(item)} key={item}><RIcon/><span>{item}</span>{reminder===item&&<Check/>}</button>})}</div><button className="advanced-toggle" onClick={()=>setAdvanced(v=>!v)}><Settings2/><span>{advanced?'收起更多设置':'更多设置'}</span><ChevronDown className={advanced?'up':''}/></button>{advanced&&<div className="quick-advanced"><div className="quick-fields"><label className="direction-picker-field"><span><Compass/> 所属方向</span><button className="direction-picker-trigger" onClick={()=>setDirectionOpen(v=>!v)}><span>{tag}<small>{realm.name} · {realm.note}</small></span><ChevronDown/></button>{directionOpen&&<div className="direction-picker-menu">{realms.map(r=><section key={r.name}><h4 style={{color:r.color}}>{r.name} · {r.note}</h4>{r.directions.map(d=><button className={tag===d?'active':''} onClick={()=>{setTag(d);setDirectionOpen(false)}} key={d}><span>{d}</span>{tag===d&&<Check/>}</button>)}</section>)}</div>}</label><label><span><CalendarDays/> 日期</span><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label><span><Clock3/> 时间（可选）</span><input type="time" value={time} onChange={e=>setTime(e.target.value)}/></label></div><div className="duration-field"><span><Timer/> 预计时长</span><div>{['30分钟','1小时','2小时','半天'].map(item=><button className={duration===item?'active':''} onClick={()=>setDuration(item)} key={item}>{item}</button>)}</div></div><label className="quick-note"><span>备注（可选）</span><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="地点、准备物品或需要留意的内容…"/></label></div>}<button className="quick-save" disabled={!title.trim()} onClick={save}><Check/> 保存待办</button></section></div>}

function InspirationMemo({close}){const [draft,setDraft]=useState(''),[memos,setMemos]=useState([{id:1,text:'周末去旧书店看看旅行随笔',time:'刚刚',pinned:true,done:false},{id:2,text:'试试把阳台的傍晚光线拍成一组照片',time:'昨天',pinned:false,done:false},{id:3,text:'记下最近反复想到的三个关键词',time:'8月9日',pinned:false,done:true}]);const add=()=>{if(!draft.trim())return;setMemos(v=>[{id:Date.now(),text:draft.trim(),time:'刚刚',pinned:false,done:false},...v]);setDraft('')};const update=(id,patch)=>setMemos(v=>v.map(m=>m.id===id?{...m,...patch}:m));const sorted=[...memos].sort((a,b)=>Number(b.pinned)-Number(a.pinned));return <div className="modal-backdrop inspiration-backdrop" onClick={close}><section className="inspiration-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close} aria-label="关闭"><X/></button><header><span><NotebookPen/></span><div><h2>灵感备忘</h2><p>想到什么就先放在这里，不必分类。</p></div></header><div className="inspiration-capture"><textarea autoFocus value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')add()}} placeholder="写下一闪而过的念头…"/><button disabled={!draft.trim()} onClick={add}><Plus/> 记下来</button><small>Ctrl + Enter 快速保存</small></div><div className="inspiration-list-head"><span>全部灵感</span><b>{memos.length}</b></div><div className="inspiration-list">{sorted.map(memo=><article className={`${memo.pinned?'pinned ':''}${memo.done?'done':''}`} key={memo.id}><button className="memo-check" onClick={()=>update(memo.id,{done:!memo.done})} aria-label={memo.done?'恢复':'标记已整理'}>{memo.done?<Check/>:null}</button><div><p>{memo.text}</p><small>{memo.time}{memo.pinned?' · 已置顶':''}</small></div><div className="memo-actions"><button className={memo.pinned?'active':''} onClick={()=>update(memo.id,{pinned:!memo.pinned})} title="置顶" aria-label="置顶"><Pin/></button><button onClick={()=>setMemos(v=>v.filter(m=>m.id!==memo.id))} title="删除" aria-label="删除"><Trash2/></button></div></article>)}</div></section></div>}

function Modal({type,close,navigate,tasks,setTasks}){if(!type)return null;if(type==='note')return <InspirationMemo close={close}/>;if(type==='addTodo')return <QuickTodoModal close={close} setTasks={setTasks}/>;if(type.startsWith('realmModal-'))return <RealmModal realm={realms[Number(type.split('-')[1])]} close={close} tasks={tasks} setTasks={setTasks}/>;const map={search:['搜索','搜索方向、事项、记录或待办…'],notice:['通知','没有需要立即处理的通知。'],sync:['登录并同步','登录后可在不同设备间同步生活数据。'],settings:['偏好设置','调整显示、提醒与数据选项。'],help:['使用帮助','版图用来理解生活，事项用来记录开展，待办只承接具体提醒。'],addRoutine:['添加日常照顾','写下想经常回来的事情，不设置连续天数。'],addMatter:['新增事项','选择所属方向，记录它现在的状态。'],matterDetail:['事项内容','在这里整理相关记录、资料与最近状态。'],profile:['编辑个人资料','修改称呼、头像与个人说明。']};if(type==='gotoTodo'){navigate('todo');close();return null}const [title,desc]=map[type]||['功能','该功能正在这里展开。'];const add=()=>close();return <div className="modal-backdrop" onClick={close}><section className="modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><span className="modal-icon">{type==='search'?<Search/>:<Sparkles/>}</span><h2>{title}</h2><p>{desc}</p>{['search','addRoutine','addMatter','profile'].includes(type)&&<input autoFocus placeholder={type==='search'?'输入关键词…':'在这里写下内容…'}/>}<button className="modal-primary" onClick={add}>{type==='search'?'搜索':'保存'}</button></section></div>}
function QuickSidebar({page,navigate,openModal,collapsed,setCollapsed}){const [active,setActive]=useState('dashboard-top'),items=[['dashboard-top','首页',Home],['life-map','人生版图',Compass],['life-content','生活内容',BookOpen],['today-todos','今日行动',ListChecks],['daily-review','本日记录',CheckCircle2]];const jump=id=>{setActive(id);if(page!=='today')navigate('today');window.setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'}),page==='today'?0:80)};return <aside className={`quick-sidebar ${collapsed?'is-collapsed':''}`} aria-label="板块快捷导航"><nav>{items.map(([id,label,Icon])=><button className={active===id?'active':''} onClick={()=>jump(id)} title={label} aria-label={label} key={id}><Icon/><span>{label}</span></button>)}</nav><footer><button onClick={()=>openModal('note')} title="灵感" aria-label="灵感"><Lightbulb/></button><button onClick={()=>openModal('profilePanel')} title="设置" aria-label="设置"><Settings/></button><button className="sidebar-toggle" onClick={()=>setCollapsed(v=>!v)} title={collapsed?'展开侧边栏':'收起侧边栏'} aria-label={collapsed?'展开侧边栏':'收起侧边栏'}>{collapsed?<PanelLeftOpen/>:<PanelLeftClose/>}</button></footer></aside>}

function MobileNav({page,navigate,openModal}){return <nav className="mobile-nav"><button className={page==='today'?'active':''} onClick={()=>navigate('today')}><Home/><span>首页</span></button><button className={page==='map'?'active':''} onClick={()=>navigate('map')}><Compass/><span>版图</span></button><button className="add" aria-label="新增待办" onClick={()=>openModal('addTodo')}><Plus/></button><button className={page==='todo'?'active':''} onClick={()=>navigate('todo')}><ListChecks/><span>待办</span></button><button className={page==='profile'?'active':''} onClick={()=>navigate('profile')}><CircleUserRound/><span>我的</span></button></nav>}

function App(){const [page,setPage]=useState('today'),[modal,setModal]=useState(null),[tasks,setTasks]=useState(initialTasks),[sidebarCollapsed,setSidebarCollapsed]=useState(false);const navigate=p=>{if(p.startsWith('todoEdit-')){setModal(p);return}setPage(p);window.scrollTo({top:0,behavior:'smooth'})};let content;if(page==='map')content=<MapPage navigate={navigate} openModal={setModal}/>;else if(page==='matters')content=<MattersPage navigate={navigate} openModal={setModal}/>;else if(page==='todo')content=<TodoPage navigate={navigate} openModal={setModal} tasks={tasks} setTasks={setTasks}/>;else if(page==='profile')content=<ProfilePage navigate={navigate} openModal={setModal}/>;else if(page.startsWith('realm-'))content=<RealmPage realm={realms[Number(page.split('-')[1])]} navigate={navigate} openModal={setModal}/>;else content=<Dashboard navigate={navigate} openModal={setModal} tasks={tasks} setTasks={setTasks}/>;const close=()=>setModal(null);return <div className={`shell with-quick-sidebar ${sidebarCollapsed?'sidebar-collapsed':''}`}><QuickSidebar page={page} navigate={navigate} openModal={setModal} collapsed={sidebarCollapsed} setCollapsed={setSidebarCollapsed}/><main className="app">{content}<MobileNav page={page} navigate={navigate} openModal={setModal}/></main>{modal?.startsWith('todoEdit-')?<TodoEditModal task={tasks.find(t=>t.id===Number(modal.split('-')[1]))} setTasks={setTasks} close={close}/>:modal==='notice'?<NotificationPanel close={close}/>:modal==='profilePanel'?<ProfilePanel close={close} openModal={setModal}/>:modal==='login'?<LoginModal close={close}/>:modal==='addDirection'?<AddDirectionModal close={close}/>:modal?.startsWith('content-')?<ContentDetailModal item={matters[Number(modal.split('-')[1])]} tasks={tasks} setTasks={setTasks} openModal={setModal} close={close}/>:<Modal type={modal} close={close} navigate={navigate} tasks={tasks} setTasks={setTasks}/>}</div>}
function ContentDetailModal({item,tasks,setTasks,openModal,close}){const realm=realms.find(r=>r.name===item.realm),Icon=item.Icon,[adding,setAdding]=useState(false),linkedTasks=tasks.filter(task=>task.tag===item.title),activeTasks=linkedTasks.filter(task=>!task.done),completedTasks=linkedTasks.filter(task=>task.done);const add=title=>{setTasks(v=>[...v,{id:Date.now(),title,tag:item.title,time:'未设置时间',level:'normal'}]);setAdding(false)};return <div className="modal-backdrop content-detail-backdrop" onClick={close}><section className="content-detail-modal" style={{'--c':realm.color,'--t':realm.tint}} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><header><span><Icon/></span><div><h2>{item.title}</h2><p>{item.realm} · {realm.note}</p></div></header><div className="content-overview"><div><span>当前状态</span><b>{item.state}</b></div><p>{item.note}。这里汇总这个方向下正在推进和已经完成的具体待办。</p><div className="content-numbers"><span><b>{linkedTasks.length}</b> 全部待办</span><span><b>{activeTasks.length}</b> 正在推进</span><span><b>{completedTasks.length}</b> 已经完成</span></div></div><div className="content-detail-body"><section><div className="detail-heading"><div><h3>具体内容</h3><p>与“{item.title}”有关、现在需要处理的具体事情</p></div><button onClick={()=>setAdding(true)}><Plus/> 添加待办</button></div><div className="content-part-grid todo-link-grid">{activeTasks.length?activeTasks.map(task=><article key={task.id} role="button" tabIndex="0" onClick={()=>openModal(`todoEdit-${task.id}`)} onKeyDown={e=>e.key==='Enter'&&openModal(`todoEdit-${task.id}`)}><span><ListChecks/></span><div><h4>{task.title}</h4><p>{task.time}</p></div><ChevronRight/></article>):<div className="direction-todo-empty"><CheckCircle2/><b>暂时没有待办</b><p>需要行动时再从这里添加即可。</p></div>}</div></section><aside className="completed-todos"><div className="detail-heading"><div><h3>最近完成</h3><p>已经处理过的事情会留在这里</p></div></div>{completedTasks.length?completedTasks.slice(0,4).map(task=><button className="happening-item" key={task.id} onClick={()=>openModal(`todoEdit-${task.id}`)}><span><Check/></span><div><b>{task.title}</b><small>{task.tag} · {task.time}</small></div></button>):<div className="completed-empty"><CheckCircle2/><span>完成的待办会留在这里</span></div>}</aside></div></section>{adding&&<ContentCreateModal item={item} realm={realm} close={()=>setAdding(false)} add={add}/>}</div>}
function NotificationPanel({close}){const [tab,setTab]=useState('全部'),[readAll,setReadAll]=useState(false);const notices=[{group:'重要提醒',category:'待办与事项',title:'10:00 整理周报材料',desc:'还有 15 分钟开始',time:'09:45',icon:Clock3,tone:'amber'},{group:'重要提醒',category:'待办与事项',title:'皮肤科复诊提醒',desc:'今天 18:00 · 健康',time:'今天',icon:CalendarDays,tone:'rose'},{group:'重要提醒',category:'内容与方向',title:'旅行灵感已有新记录',desc:'Soul · 旅行探索',time:'昨天',icon:Sparkles,tone:'green'},{group:'今天',category:'待办与事项',title:'待办已完成',desc:'你已完成「采购游泳用品」',time:'11:20',icon:Check,tone:'green'},{group:'今天',category:'内容与方向',title:'时间轴已更新',desc:'一项待办已安排到 15:00',time:'09:10',icon:CalendarDays,tone:'blue'},{group:'今天',category:'系统通知',title:'系统更新',desc:'新版交互与显示细节已应用',time:'08:30',icon:Settings2,tone:'violet'},{group:'更早',category:'内容与方向',title:'本周内容整理完成',desc:'7 条生活记录已收录',time:'昨天 22:00',icon:Archive,tone:'amber'}];const visible=tab==='全部'?notices:notices.filter(n=>n.category===tab);return <div className="notice-backdrop" onClick={close}><aside className="notification-panel" onClick={e=>e.stopPropagation()}><header><div><h2>通知</h2>{!readAll&&<b>3</b>}</div><button onClick={close}><X/></button></header><nav>{['全部','待办与事项','内容与方向','系统通知'].map(item=><button className={tab===item?'active':''} onClick={()=>setTab(item)} key={item}>{item}</button>)}</nav><div className="notification-scroll">{['重要提醒','今天','更早'].map(group=>{const groupItems=visible.filter(n=>n.group===group);return groupItems.length?<section className="notification-group" key={group}><h3>{group}</h3>{groupItems.map((n,i)=>{const Icon=n.icon;return <button className="notification-item" key={n.title}><span className={n.tone}><Icon/>{group==='重要提醒'&&!readAll&&<i/>}</span><div><b>{n.title}</b><small>{n.desc}</small></div><time>{n.time}</time><ChevronRight/></button>})}</section>:null})}</div><footer><button><Settings2/> 通知设置</button><button onClick={()=>setReadAll(true)}>{readAll?'已全部读完':'全部标为已读'} <Check/></button></footer></aside></div>}

function TodoEditModal({task,setTasks,close}){const [title,setTitle]=useState(task?.title||''),[date,setDate]=useState('2026-08-10'),[time,setTime]=useState('15:00'),[allDay,setAllDay]=useState(false),[repeat,setRepeat]=useState('不重复'),[duration,setDuration]=useState('1 小时'),[note,setNote]=useState(''),[subtasks,setSubtasks]=useState(['准备相关资料','确认需要处理的重点']);if(!task)return null;const realm=realms.find(r=>r.directions.includes(task.tag))||realms[3],save=()=>{setTasks(v=>v.map(t=>t.id===task.id?{...t,title,time:`${date} ${allDay?'全天':time}`}:t));close()},remove=()=>{setTasks(v=>v.filter(t=>t.id!==task.id));close()};return <div className="modal-backdrop todo-edit-backdrop" onClick={close}><section className="todo-edit-modal" style={{'--c':realm.color,'--t':realm.tint}} onClick={e=>e.stopPropagation()}><button className="todo-edit-close" onClick={close} aria-label="关闭"><X/></button><header><span><ListChecks/></span><div><small>来自内容</small><b>{task.tag}</b></div></header><div className="todo-edit-heading"><div><h2>编辑待办</h2><p>整理这件需要被提醒的具体事情。</p></div><button>更多操作 <ChevronDown/></button></div><label className="todo-title-field"><span>待办标题</span><input value={title} onChange={e=>setTitle(e.target.value)}/></label><div className="todo-form-grid"><label><span>日期</span><div><CalendarDays/><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></div></label><label><span>时间（可选）</span><div><Clock3/><input type="time" value={time} onChange={e=>setTime(e.target.value)} disabled={allDay}/></div></label><label><span>重复</span><div><Repeat2/><select value={repeat} onChange={e=>setRepeat(e.target.value)}><option>不重复</option><option>每天</option><option>每周</option><option>每月</option></select></div></label><label><span>预计时长（可选）</span><div><Timer/><select value={duration} onChange={e=>setDuration(e.target.value)}><option>30 分钟</option><option>1 小时</option><option>1.5 小时</option><option>2 小时</option></select></div></label></div><label className="all-day-switch"><button type="button" className={allDay?'on':''} onClick={()=>setAllDay(v=>!v)}><i/></button><span>全天</span></label><label className="todo-note-field"><span>备注</span><textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={200} placeholder="地点、准备物品、联系方式……"/><small>{note.length}/200</small></label><section className="subtask-editor"><header><span>子事项 {subtasks.length}/5</span><button onClick={()=>subtasks.length<5&&setSubtasks(v=>[...v,'新的子事项'])}><Plus/> 添加子事项</button></header><div>{subtasks.map((item,i)=><label key={i}><button onClick={e=>e.currentTarget.classList.toggle('checked')}><Check/></button><input value={item} onChange={e=>setSubtasks(v=>v.map((x,n)=>n===i?e.target.value:x))}/><button onClick={()=>setSubtasks(v=>v.filter((_,n)=>n!==i))} aria-label="删除子事项"><X/></button></label>)}</div></section><footer><button className="delete-todo" onClick={remove}><Trash2/> 删除待办</button><div><button onClick={close}>取消</button><button>保存为模板</button><button className="save-todo" onClick={save}>保存待办</button></div></footer></section></div>}

function LifeReview({tasks,navigate}){const active=tasks.filter(t=>!t.done),completed=tasks.filter(t=>t.done),directionCount=new Set(tasks.map(t=>t.tag)).size,cards=[{label:'涉及方向',value:`${directionCount} 个`,note:'最近有内容流动的方向',icon:Compass,tone:'amber'},{label:'时间安排',value:'4 小时',note:'留给有明确时间的事',icon:Clock3,tone:'blue'},{label:'正在推进',value:`${active.length} 项`,note:'此刻仍在发生的事项',icon:ListChecks,tone:'green'},{label:'已完成',value:`${completed.length} 项`,note:'今天已经处理的事情',icon:CheckCircle2,tone:'rose'}];return <section id="daily-review" className="life-review panel"><header className="section-head"><div><h2>本日回顾</h2><p>轻轻看看最近留下了什么</p></div><time>2026年8月11日</time></header><div className="review-cards">{cards.map(({label,value,note,icon:Icon,tone})=><article className={tone} key={label}><span><Icon/></span><div><small>{label}</small><b>{value}</b><p>{note}</p></div></article>)}</div></section>}

function ContentCreateModal({item,realm,close,add}){const [name,setName]=useState(''),[kind,setKind]=useState('随时待办');const types=[['随时待办','不设置具体时间，方便之后安排',ListChecks],['指定日期','在某一天提醒自己处理',CalendarDays],['重复待办','适合经常会回来的具体事情',Repeat2]];return <div className="modal-backdrop content-create-backdrop" onClick={close}><section className="content-create-modal" style={{'--c':realm.color,'--t':realm.tint}} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><header><span><ListChecks/></span><div><h2>添加一个待办</h2><p>从“{item.title}”中拆出一件可以具体处理的事情</p></div></header><div className="create-field"><h3><i/>准备做什么？</h3><div className="direction-name"><input autoFocus maxLength={30} value={name} onChange={e=>setName(e.target.value)} placeholder="例如：阅读行业资料 / 确认沟通时间 / 整理本周材料…"/><span>{name.length}/30</span></div></div><div className="create-field"><h3><i/>来自哪个方向？</h3><div className="content-parent-card"><span>{React.createElement(item.Icon)}</span><div><b>{item.title}</b><small>{item.realm} · {realm.note}</small></div><Check/></div></div><div className="create-field"><h3><i/>如何提醒？</h3><div className="kind-picker">{types.map(([title,desc,TypeIcon])=><button className={kind===title?'selected':''} onClick={()=>setKind(title)} key={title}><span><TypeIcon/></span><div><b>{title}</b><small>{desc}</small></div><i>{kind===title&&<Check/>}</i></button>)}</div></div><button className="create-submit" disabled={!name.trim()} onClick={()=>add(name.trim())}><Plus/> 添加待办</button><button className="create-later" onClick={close}>稍后再说</button></section></div>}

function LinkedMatters({openModal,tasks}){return <div className="goals linked-goals all-linked-goals">{matters.map((item,index)=><MatterCard item={item} index={index} openModal={openModal} tasks={tasks} key={`${item.realm}-${item.title}`}/>)}</div>}

createRoot(document.getElementById('root')).render(<App/>)
function AddDirectionModal({close}){const [name,setName]=useState(''),[realmIndex,setRealmIndex]=useState(0),[kind,setKind]=useState('long'),selectedRealm=realms[realmIndex],SelectedIcon=selectedRealm.Icon;const save=()=>{if(!name.trim())return;realms[realmIndex].directions.push(name.trim());close()};const kinds=[['long',Compass,'长期方向','持续了解和经营的生活方向'],['habit',Clock3,'日常习惯','想经常回来的日常实践'],['project',CalendarDays,'一次性项目','短期项目或阶段性的具体安排']];return <div className="modal-backdrop direction-create-backdrop" onClick={close}><section className="direction-create" style={{'--create-c':selectedRealm.color,'--create-t':selectedRealm.tint}} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><header><span><SelectedIcon/></span><div><h2>开启一个新方向</h2><p>把想法放进生活，慢慢靠近想成为的自己</p></div></header><div className="create-field"><h3><i/> 我想开始什么？</h3><div className="direction-name"><input autoFocus maxLength={30} value={name} onChange={e=>setName(e.target.value)} placeholder="例如：练习游泳 / 学习摄影 / 重新开始阅读…"/><span>{name.length}/30</span></div><p><Sparkles/> 试试写成一个想长期靠近的生活方向</p></div><div className="create-field"><h3><i/> 属于哪个领域？</h3><div className="realm-picker">{realms.map((r,i)=>{const Icon=r.Icon;return <button className={realmIndex===i?'selected':''} onClick={()=>setRealmIndex(i)} key={r.name} style={{'--c':r.color,'--t':r.tint}}><span><Icon/></span><b>{r.name}</b><small>{r.note}</small></button>})}</div></div><div className="create-field"><h3><i/> 这个方向以什么方式存在？</h3><div className="kind-picker">{kinds.map(([id,Icon,title,desc])=><button className={kind===id?'selected':''} onClick={()=>setKind(id)} key={id}><span><Icon/></span><div><b>{title}</b><small>{desc}</small></div><i>{kind===id&&<Check/>}</i></button>)}</div></div><button className="create-submit" disabled={!name.trim()} onClick={save}><SelectedIcon/> 开启这个方向</button><button className="create-later" onClick={close}>稍后再说</button></section></div>}
